  1	/**
  2	 * La lectura de cada fuente administrada de `policySettings`: la remota
  3	 * (`Qq`), la MDM (`Os`) y el archivo `managed-settings.json` con su
  4	 * directorio de fragmentos `managed-settings.d` (`njr`), más la validación de
  5	 * un documento de política (`HRe`/`Ty`/`gd`). Porte de `chunk-379zyrv7.js` del
  6	 * ejecutable 2.1.283; extracción en
  7	 * `.claude/workbench/policy-settings-port-20260927T083804/`.
  8	 *
  9	 * Cada lectura devuelve lo que la composición (`./policyComposition.ts`)
 10	 * necesita para decidir qué fuente ata: los settings, sus errores, si el
 11	 * documento trae política y si cargó. Una fuente que no se pudo leer no
 12	 * cuenta como ausente: queda `didNotLoad`, para que la composición falle
 13	 * cerrado en vez de caer a la fuente siguiente.
 14	 *
 15	 * Divergencias declaradas:
 16	 * - La validación es `SettingsSchema` de este paquete, no la de 2.1.283
 17	 *   (`os`/`At`), que rescata campo a campo y registra sustitutos. Por eso no
 18	 *   hay `onlySubstitutes` por documento ni la lista `removed`, y el suelo de
 19	 *   sustitutos entre fragmentos (`pd`) no se porta. pendiente: con el esquema
 20	 *   de rescate.
 21	 * - `C$o` descarta además las claves que `Ed` reconoce como retiradas; aquí
 22	 *   cuenta toda clave de política con valor. pendiente: con `Ed`.
 23	 * - La capa remota no emite el aviso de servidores MCP retenidos (`MRe`,
 24	 *   `agn`) ni los fallos `ruled_empty` del último intento (`jx`), y
 25	 *   `servedSnapshot` es siempre falso: esos tres leen el estado de la sesión
 26	 *   remota, que este paquete aún no modela.
 27	 */
 28	import mergeWith from 'lodash-es/mergeWith.js'
 29	import { type Dirent, readdirSync, readFileSync } from 'node:fs'
 30	import { join } from 'node:path'
 31	import { getRemoteManagedSettingsSyncFromCache } from '../remote/syncCacheState.ts'
 32	import {
 33	  combineLoadState,
 34	  documentHasPolicyContent,
 35	  downgradeWslInheritErrors,
 36	  hasPolicyKeys,
 37	  hasPolicyValues,
 38	  loadStateOf,
 39	  NON_POLICY_KEYS,
 40	  type PolicyError,
 41	  type PolicyLoadState,
 42	  type PolicyRead,
 43	} from './policyComposition.ts'
 44	import { mergeManagedValue } from './policyMerge.ts'
 45	import { SettingsSchema } from './types.ts'
 46	import { formatZodError } from './validation.ts'
 47	import { sanitizeCrossSessionInbound } from './crossSessionInbound.ts'
 48	
 49	type PolicyDocument = Record<string, unknown>
 50	
 51	/** Una fuente leída, con sus errores. */
 52	export type PolicySourceRead = PolicyRead & { errors: PolicyError[] }
 53	
 54	/** Lo que la composición inyecta: las fuentes que no son archivos. */
 55	export type PolicySourceContext = {
 56	  remote?: () => PolicyDocument | null
 57	  mdm?: () => PolicySourceRead | null
 58	}
 59	
 60	/** El sistema de archivos que lee `managed-settings.json` y sus fragmentos. */
 61	export type PolicyFiles = {
 62	  readFile(path: string): string
 63	  listDirectory(path: string): Pick<Dirent, 'name' | 'isFile' | 'isSymbolicLink'>[]
 64	}
 65	
 66	export const NODE_POLICY_FILES: PolicyFiles = {
 67	  readFile: path => readFileSync(path, 'utf8'),
 68	  listDirectory: path => readdirSync(path, { withFileTypes: true }),
 69	}
 70	
 71	const REMOTE_SOURCE = 'remote managed settings'
 72	const MANAGED_FILE = 'managed-settings.json'
 73	const DROP_IN_DIRECTORY = 'managed-settings.d'
 74	
 75	function errnoOf(error: unknown): string | undefined {
 76	  return typeof error === 'object' && error !== null && 'code' in error ? String((error as { code: unknown }).code) : undefined
 77	}
 78	
 79	/** `C$o`: el documento escribe alguna clave de política con valor. */
 80	function writesPolicy(document: PolicyDocument, settings: PolicyDocument | null): boolean {
 81	  return Object.entries(document).some(([key, value]) => value !== null && !(NON_POLICY_KEYS as readonly string[]).includes(key))
 82	    || (settings !== null && hasPolicyKeys(settings))
 83	}
 84	
 85	type DocumentRead = PolicySourceRead & { loadState: PolicyLoadState; documentHasPolicyContent: boolean }
 86	
 87	/** `md`: la validación de cada documento, por documento y por nombre de fuente. */
 88	const validated = new WeakMap<object, Map<string, DocumentRead>>()
 89	
 90	/** `Ty`. */
 91	function validatePolicyDocument(document: PolicyDocument, file: string): DocumentRead {
 92	  const candidate = structuredClone(document)
 93	  const warnings = sanitizeCrossSessionInbound(candidate, file, { policySource: true })
 94	  const parsed = SettingsSchema().safeParse(candidate)
 95	  if (!parsed.success) {
 96	    return { settings: null, errors: [...warnings, ...formatZodError(parsed.error, file)], documentHasPolicyContent: false, loadState: 'didNotLoad' }
 97	  }
 98	  const data = parsed.data as PolicyDocument
 99	  const settings = Object.keys(data).length > 0 ? data : null
100	  return { settings, errors: warnings, documentHasPolicyContent: writesPolicy(document, settings), loadState: 'loaded' }
101	}
102	
103	/** `gd`: cada llamada recibe su copia, para que nadie mute la de la caché. */
104	function copyOf(read: DocumentRead): DocumentRead {
105	  return { ...read, settings: read.settings && structuredClone(read.settings), errors: read.errors.map(error => ({ ...error })) }
106	}
107	
108	/** `HRe`: valida un documento de política con el nombre de su fuente. */
109	export function readPolicyDocument(document: PolicyDocument, file: string): DocumentRead {
110	  let byFile = validated.get(document)
111	  let read = byFile?.get(file)
112	  if (!read) {
113	    read = validatePolicyDocument(document, file)
114	    if (!byFile) validated.set(document, (byFile = new Map()))
115	    byFile.set(file, read)
116	  }
117	  return copyOf(read)
118	}
119	
120	/** `Qq`: la capa remota, desde la caché de ajustes gestionados. */
121	export function readRemotePolicy(context: PolicySourceContext): PolicySourceRead & { servedSnapshot: boolean } {
122	  const document = context.remote ? context.remote() : (getRemoteManagedSettingsSyncFromCache() as PolicyDocument | null)
123	  if (!document || Object.keys(document).length === 0) {
124	    return { settings: null, errors: [], servedSnapshot: false, documentHasPolicyContent: false }
125	  }
126	  const { settings, errors, documentHasPolicyContent } = readPolicyDocument(document, REMOTE_SOURCE)
127	  return { settings, errors, servedSnapshot: false, documentHasPolicyContent }
128	}
129	
130	/** `Os`: la capa MDM (plist en macOS, HKLM en Windows). */
131	export function readMdmPolicy(context: PolicySourceContext): PolicySourceRead {
132	  const mdm = context.mdm?.()
133	  if (!mdm) return { settings: null, errors: [], documentHasPolicyContent: false, loadState: 'absent' }
134	  return {
135	    settings: mdm.settings && Object.keys(mdm.settings).length > 0 ? mdm.settings : null,
136	    errors: downgradeWslInheritErrors(mdm.errors, () => readRemotePolicy(context)),
137	    documentHasPolicyContent: documentHasPolicyContent(mdm),
138	    loadState: loadStateOf(mdm),
139	    ...(mdm.onlySubstitutes && { onlySubstitutes: mdm.onlySubstitutes }),
140	  }
141	}
142	
143	/** `BUt`. */
144	function unreadable(file: string, error: unknown, kind: 'file' | 'directory' = 'file'): PolicyError {
145	  const what = kind === 'directory' ? 'Managed settings drop-in directory' : 'Settings file'
146	  return { file, path: '', message: `${what} could not be read: ${error instanceof Error ? error.message : String(error)}`, severity: 'fatal', errorClass: 'unreadable' }
147	}
148	
149	/** `ugn`, para un documento administrado que no escribe el usuario. */
150	function notAnObject(file: string): PolicyError {
151	  return { file, path: '', message: 'Managed settings document could not be parsed as a JSON object; none of its settings are in effect. Fix or remove it.', startupFatal: true }
152	}
153	
154	/** `Pne`/`Gye`/`Cd`: un documento administrado del disco. */
155	function readManagedDocument(path: string, files: PolicyFiles): PolicySourceRead {
156	  let content: string
157	  try {
158	    content = files.readFile(path)
159	  } catch (error) {
160	    if (errnoOf(error) === 'ENOENT') return { settings: null, errors: [], loadState: 'absent' }
161	    return { settings: null, errors: [unreadable(path, error)], loadState: 'didNotLoad' }
162	  }
163	  if (content.trim() === '') return { settings: {}, errors: [], loadState: 'loaded' }
164	  let document: unknown
165	  try {
166	    document = JSON.parse(content)
167	  } catch {
168	    document = null
169	  }
170	  if (typeof document !== 'object' || document === null || Array.isArray(document)) {
171	    return { settings: null, errors: [notAnObject(path)], loadState: 'didNotLoad' }
172	  }
173	  return readPolicyDocument(document as PolicyDocument, path)
174	}
175	
176	/** `V2o`/`b6`: un fragmento es un `.json` visible, archivo o enlace. */
177	function isFragment(entry: Pick<Dirent, 'name' | 'isFile' | 'isSymbolicLink'>): boolean {
178	  return (entry.isFile() || entry.isSymbolicLink()) && entry.name.endsWith('.json') && !entry.name.startsWith('.')
179	}
180	
181	/** `njr`: `managed-settings.json` y, encima, sus fragmentos en orden de nombre. */
182	export function readFilePolicy(directory: string, files: PolicyFiles = NODE_POLICY_FILES): PolicySourceRead {
183	  const errors: PolicyError[] = []
184	  let merged: PolicyDocument = {}
185	  let found = false
186	  let authored = false
187	  let hasContent = false
188	  let loadState: PolicyLoadState = 'absent'
189	
190	  const apply = (read: PolicySourceRead) => {
191	    errors.push(...read.errors)
192	    hasContent ||= documentHasPolicyContent(read)
193	    loadState = combineLoadState(loadState, loadStateOf(read))
194	    const { settings } = read
195	    if (!settings || Object.keys(settings).length === 0) return
196	    merged = mergeWith(merged, settings, mergeManagedValue)
197	    found = true
198	    if (hasPolicyValues(settings) && !read.onlySubstitutes) authored = true
199	  }
200	
201	  apply(readManagedDocument(join(directory, MANAGED_FILE), files))
202	  const dropIns = join(directory, DROP_IN_DIRECTORY)
203	  try {
204	    const names = files.listDirectory(dropIns).filter(isFragment).map(entry => entry.name).sort()
205	    for (const name of names) apply(readManagedDocument(join(dropIns, name), files))
206	  } catch (error) {
207	    const code = errnoOf(error)
208	    if (code !== 'ENOENT' && code !== 'ENOTDIR') {
209	      errors.push(unreadable(dropIns, error, 'directory'))
210	      loadState = 'didNotLoad'
211	    }
212	  }
213	
214	  const settings = found && hasPolicyKeys(merged) ? merged : null
215	  return {
216	    settings,
217	    errors,
218	    documentHasPolicyContent: hasContent,
219	    loadState,
220	    ...(settings !== null && !authored && hasPolicyValues(settings) && { onlySubstitutes: true }),
221	  }
222	}

